def format_combat_turns_uk(value):
    """Return a Ukrainian turn count with correct plural form."""
    try:
        value = max(0, int(value))
    except Exception:
        value = 0

    mod_10 = value % 10
    mod_100 = value % 100

    if mod_10 == 1 and mod_100 != 11:
        word = "хід"
    elif mod_10 in (2, 3, 4) and mod_100 not in (12, 13, 14):
        word = "ходи"
    else:
        word = "ходів"

    return f"{value} {word}"

