    def pvp_round_callback(call):
        parts=str(call.data).split(":")
        if len(parts)<7: return
        mode=parts[2]
        try: bid,rnd,rev=int(parts[3]),int(parts[4]),int(parts[5])
        except (TypeError,ValueError): return
        battle=get_pvp_battle(bid)
