        if result.get("both_ready"):
            resolved=resolve_persisted_pvp_round(bid,rnd,rev,seed=(bid*100000+rnd))
            if resolved.get("resolved"):
                broadcast_pvp_round_log(bot, bid, resolved.get("round_payload"))
