        lines = [f"📦 <b>{name}</b>", ""]
    lines.extend(_trade_snapshot_lines_12_6_2(snapshot, include_quantity=preview.get("is_stack")))
    if preview.get("is_equipment"):
        lines.extend(["", "Додати цей предмет до пропозиції?"])
