        "bonus_wis": "🦉 Мудрість",
        "bonus_sta": "🛡 Витривалість",
        "pdef": "🛡 Фіз. захист",
        "mdef": "🔮 Маг. захист",
    }
    bonuses = []
    for key, label in stat_labels.items():
        value = int(snapshot.get(key) or 0)
